const getCards = `-- name: GetCards :many
SELECT
    card_id,
    user_id,
    card_number,
    card_type,
    expire_date,
    cvv,
    card_provider,
    created_at,
    updated_at,
    COUNT(*) OVER () AS total_count
FROM cards
WHERE
    deleted_at IS NULL
    AND (
        $1::TEXT IS NULL
        OR card_number ILIKE '%' || $1 || '%'
        OR card_type ILIKE '%' || $1 || '%'
        OR card_provider ILIKE '%' || $1 || '%'
    )
ORDER BY card_id
LIMIT $2
OFFSET
    $3
`

type GetCardsParams struct {
	Column1 string `json:"column_1"`
	Limit   int32  `json:"limit"`
	Offset  int32  `json:"offset"`
}

type GetCardsRow struct {
	CardID       int32            `json:"card_id"`
	UserID       int32            `json:"user_id"`
	CardNumber   string           `json:"card_number"`
	CardType     string           `json:"card_type"`
	ExpireDate   pgtype.Date      `json:"expire_date"`
	Cvv          string           `json:"cvv"`
	CardProvider string           `json:"card_provider"`
	CreatedAt    pgtype.Timestamp `json:"created_at"`
	UpdatedAt    pgtype.Timestamp `json:"updated_at"`
	TotalCount   int64            `json:"total_count"`
}

// GetCards: Retrieves paginated list of active cards with search capability
// Purpose: List all active cards for management UI
// Parameters:
//
//	$1: search_term - Optional text to filter cards by number, type or provider (NULL for no filter)
//	$2: limit - Maximum number of records to return
//	$3: offset - Number of records to skip for pagination
//
// Returns:
//
//	All card fields plus total_count of matching records
//
// Business Logic:
//   - Excludes soft-deleted cards (deleted_at IS NULL)
//   - Supports partial text matching on card_number, card_type and card_provider fields (case-insensitive)
//   - Returns cards ordered by card_id
//   - Provides total_count for pagination calculations
func (q *Queries) GetCards(ctx context.Context, arg GetCardsParams) ([]*GetCardsRow, error) {
	rows, err := q.db.Query(ctx, getCards, arg.Column1, arg.Limit, arg.Offset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*GetCardsRow
	for rows.Next() {
		var i GetCardsRow
		if err := rows.Scan(
			&i.CardID,
			&i.UserID,
			&i.CardNumber,
			&i.CardType,
			&i.ExpireDate,
			&i.Cvv,
			&i.CardProvider,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

