const trashCard = `-- name: TrashCard :one
UPDATE cards
SET
    deleted_at = current_timestamp
WHERE
    card_id = $1
    AND deleted_at IS NULL
RETURNING
    card_id,
    user_id,
    card_number,
    card_type,
    expire_date,
    cvv,
    card_provider,
    created_at,
    updated_at,
    deleted_at
`

type TrashCardRow struct {
	CardID       int32            `json:"card_id"`
	UserID       int32            `json:"user_id"`
	CardNumber   string           `json:"card_number"`
	CardType     string           `json:"card_type"`
	ExpireDate   pgtype.Date      `json:"expire_date"`
	Cvv          string           `json:"cvv"`
	CardProvider string           `json:"card_provider"`
	CreatedAt    pgtype.Timestamp `json:"created_at"`
	UpdatedAt    pgtype.Timestamp `json:"updated_at"`
	DeletedAt    pgtype.Timestamp `json:"deleted_at"`
}

// TrashCard: Soft-deletes a card by marking deleted_at
// Purpose: Temporarily remove a card without deleting it permanently
// Parameters:
//
//	$1: card_id - Identifier of the card to be trashed
//
// Returns: Nothing
// Business Logic:
//   - Sets deleted_at to current timestamp
//   - Only affects cards not already trashed
func (q *Queries) TrashCard(ctx context.Context, cardID int32) (*TrashCardRow, error) {
	row := q.db.QueryRow(ctx, trashCard, cardID)
	var i TrashCardRow
	err := row.Scan(
		&i.CardID,
		&i.UserID,
		&i.CardNumber,
		&i.CardType,
		&i.ExpireDate,
		&i.Cvv,
		&i.CardProvider,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return &i, err
}

